                string qualityPath=Path.Combine(session,"diagnostics/data-quality.json");if(File.Exists(qualityPath)){var quality=Json.Read(qualityPath);var checks=DiagnosticData.Get(quality,"checks") as Dictionary<string,object>??M();var frames=DiagnosticData.Get(checks,"frames") as Dictionary<string,object>??M();Check(L(frames,"wall_clock_steps_over_5ms")==0,"Cannot align capture UTC after a detected wall-clock step");}
